if b4_v2_preds:
    format_and_save_trec_run(b4_v2_preds, f"{GROUP_ID}_B4_SBERT_V2_MPNet_TestFull", SUBMISSION_DIR, f"{GROUP_ID}_B4_SBERT_V2_MPNet_TestFull.txt", generate_pseudo_scores=True)

